fn describe(items: List(String)) -> String {
  case items {
    [] -> "empty"
    [one] -> "only " <> one
    [first, ..rest] ->
      first <> " and " <> int.to_string(list.length(rest)) <> " more"
  }
}

pub fn main() {
  io.println(describe([]))
  io.println(describe(["tea"]))
  io.println(describe(["milk", "bread", "rice"]))
}

