import gleam/int
import gleam/io
import gleam/string

fn sum(numbers: List(Int)) -> Int {
  case numbers {
    [] -> 0
    [first, ..rest] -> first + sum(rest)
  }
}

fn double_all(numbers: List(Int)) -> List(Int) {
  case numbers {
    [] -> []
    [first, ..rest] -> [first * 2, ..double_all(rest)]
  }
}

pub fn main() {
  io.println(int.to_string(sum([1, 2, 3, 4])))
  io.println(string.inspect(double_all([1, 2, 3])))
}

