fn sum_to(n: Int, acc: Int) -> Int {
  case n {
    0 -> acc
    _ -> sum_to(n - 1, acc + n)
  }
}

pub fn main() {
  io.println(int.to_string(sum_to(100, 0)))
  io.println(int.to_string(sum_to(1_000_000, 0)))
}

