import gleam/float
import gleam/io

type Shape {
  Circle(radius: Float)
  Rectangle(width: Float, height: Float)
}

fn area(shape: Shape) -> Float {
  case shape {
    Circle(r) -> 3.0 *. r *. r
    Rectangle(w, h) -> w *. h
  }
}

pub fn main() {
  io.println(float.to_string(area(Circle(2.0))))
  io.println(float.to_string(area(Rectangle(2.0, 3.5))))
}

